/* Offline support. Precaches every file listed in asset-manifest.js (generated by
   scripts/parse-itinerary.py) on first load, then serves the site from cache.
   A new ASSET_VERSION (any content change) installs a fresh cache and drops the old one.
   Cross-origin requests (map tiles, maps links) are left to the network. */
importScripts('asset-manifest.js');

var CACHE = 'trip-' + self.ASSET_VERSION;

self.addEventListener('install', function (event) {
  event.waitUntil(
    caches.open(CACHE).then(function (cache) {
      return cache.addAll(self.ASSETS.map(function (u) { return new Request(u, { cache: 'reload' }); }));
    }).then(function () { return self.skipWaiting(); })
  );
});

self.addEventListener('activate', function (event) {
  event.waitUntil(
    caches.keys().then(function (keys) {
      return Promise.all(keys.filter(function (k) { return k.indexOf('trip-') === 0 && k !== CACHE; })
        .map(function (k) { return caches.delete(k); }));
    }).then(function () { return self.clients.claim(); })
  );
});

self.addEventListener('fetch', function (event) {
  var req = event.request;
  if (req.method !== 'GET') return;
  var url = new URL(req.url);
  if (url.origin !== self.location.origin) return;
  event.respondWith(
    caches.open(CACHE).then(function (cache) {
      return cache.match(req, { ignoreSearch: true }).then(function (hit) {
        if (hit) return hit;
        return fetch(req).catch(function () {
          // Offline and not cached: any page navigation gets the app shell.
          return req.mode === 'navigate' ? cache.match('./') : Response.error();
        });
      });
    })
  );
});
